actor MemoryCache<Key: Hashable, Value> {
    private var storage: [Key: Value] = [:]
    func get(_ key: Key) -> Value? { storage[key] }
    func set(_ key: Key, value: Value) { storage[key] = value }
    func clear() { storage.removeAll() }
}

func fetchAllMetrics(urls: [URL]) async -> [Metric] {
    await withTaskGroup(of: Metric?.self) { group in
        for url in urls {
            group.addTask { await fetchSingleMetric(url) }
        }
        var results: [Metric] = []
        for await metric in group {
            if let m = metric { results.append(m) }
        }
        return results
    }
}

@propertyWrapper
struct Clamped<T: Comparable> {
    var value: T
    let range: ClosedRange<T>
    init(wrappedValue: T, _ range: ClosedRange<T>) {
        self.range = range
        self.value = min(max(wrappedValue, range.lowerBound), range.upperBound)
    }
    var wrappedValue: T {
        get { value }
        set { value = min(max(newValue, range.lowerBound), range.upperBound) }
    }
}

